import { onLCP, onINP, onCLS } from "web-vitals";

function sendMetric(metric: { name: string; value: number; id: string }) {
  const body = JSON.stringify(metric);
  navigator.sendBeacon(
    "/api/performance",
    new Blob([body], { type: "application/json" })
  );
}

onLCP(sendMetric);
onINP(sendMetric);
onCLS(sendMetric);

