"use client";

import DOMPurify from "dompurify";

export default function SafeArticle({ html }: { html: string }) {
  const safeHTML = DOMPurify.sanitize(html);
  return (
    <article dangerouslySetInnerHTML={{ __html: safeHTML }} />
  );
}
